      "title": "そもそも「ルネサンス」ってなんだろう？",
      "body": [
        "こうして中世の西ヨーロッパでは「12世紀ルネサンス」が起き、さらに14世紀になると、ギリシア・ローマの文献を正確に研究することで、教会や神学にしばられずに人間の精神を追求しようとする「人文主義【ヒューマニズム】」が現れた。しかも、黒死病【ペスト】の大流行や戦乱で政治も社会も混乱していたから（「14世紀の危機」）、「どんな人間でも必ず死ぬ。“生きること”は価値のあることなんだ。それを大切にするギリシア・ローマ文化はなんてすばらしいんだろう」と感じたことが、中世の価値観にとらわれない考え方を生み出された背景とも考えられるね。",
        "一方で、こうした動きはあくまでも「中世の枠内」で起こったんだ。だって、ルネサンスのパトロン（保護者）になったのは、フィレンツェのメディチ家やミラノのヴィスコンティ家といった中世都市の有力な大商人や銀行家で、都市（コムーネ【自治都市】）の支配者だ。芸術作品の多くは、こうした有力者や、さらには教皇・国王などの注文を受けて制作され、邸宅や教会、宮殿の装飾など、権力を示すために使われたんだよ。"
      ],
