      "title": "いち早くルネサンスが花開いたフィレンツェ！",
      "body": [
        "メディチ家を中心に毛織物業や金融業で繁栄したフィレンツェでは、いち早くルネサンスが花開いたよ。",
        "貴族出身の詩人ダンテの著した「神曲」は、文学におけるルネサンスの先駆っていわれている。描かれているのは地獄・煉獄・天上界だから神の世界そのものなんだけど、内容が「死別した恋人との再会」って、いきなり人間的だ。だからダンテはミサや学問の言語であるラテン語じゃなく、日常語であるトスカナ語（イタリア語）を使って書いた。しかも案内役は古代ローマの詩人ウェルギリウスね。",
        "続いて、人文主義の先駆者といわれるペトラルカは、キリスト教以前のラテン語（ローマの古典）を研究してたらラテン文学にハマり、ついにはラテン語詩集「アフリカ」を著した。さらに、恋人にはイタリア語の「叙情詩集【カンツォニエーレ】」を捧げたんだ。そして、14世紀後半にはボッカチオがペストの流行を題材に「デカメロン」をつくった。ペストから逃れて家にこもった男女10人が面白い話に興ずるんだけど、ヒマなときに恋愛話になるのは今も昔も同じだね。禁欲なはずの聖職者が好き放題しちゃったヤバイ暴露話とかも出てくる痛快小説で、「神曲」に対して「人曲」ともいわれるよ！"
      ],
