      "title": "いち早くルネサンスが花開いたフィレンツェ！",
      "body": [
        "芸術では、遠近法や鮮やかな色彩を使って、人間の表情や肉体を写実的に描く絵画がつくられた。こうした作風はルネサンス様式といわれ、「聖フランチェスコの生涯」などを描いた画家のジョットが先駆者だ。さらに、ドナテルロはギリシア彫刻をまねてルネサンス彫刻を確立した。15世紀になるとメディチ家が繁栄し、コジモ＝デ＝メディチが創設したプラトン学園「アカデミー」では多くの古典研究が展開され、ルネサンス様式建築の先駆者ブルネレスキや、「春」や「ヴィーナスの誕生」で官能的な女性の美しさを表現したボッティチェリが活躍したよ。",
        "しかし、15世紀末になるとフランス軍が侵入し（イタリア戦争）、それに乗じてドミニコ派の修道士サヴォナローラが政権を握ると、フィレンツェの政治は大混乱。この混乱を経験した外交官のマキァヴェリは「君主論」を著し、外国勢力の排除とイタリア統一のためには「獅子のように勇猛で狐のように狡猾（する賢い）な、強大な君主が必要だ！」って主張し、のちにこの政治手法がマキァヴェリズムと呼ばれるようになるよ。"
      ],
