      "title": "イタリア＝ルネサンスの最盛期と、その終焉",
      "body": [
        "15世紀後半から16世紀にかけてイタリア＝ルネサンスは最盛期を迎え、いわゆる「ルネサンスの三大巨匠」が活躍するよ。まず、絵画・彫刻・科学・土木などあらゆる分野で活躍したレオナルド＝ダ＝ヴィンチは、ルネサンス期の理想とされた「万能人」だ！　絵画では遠近法を確立して、ミラノの聖マリア＝デッレ＝グラツィエ教会の壁画「最後の晩餐」や、神秘的な微笑みの「モナ＝リザ」などを描いた。晩年、フランス国王フランソワ1世に招かれたから、「モナ＝リザ」はパリのルーブル美術館にあるよ。続いて、「ダヴィデ像」などの彫刻で有名なミケランジェロは、ローマでは教皇ユリウス2世の保護を受け、ヴァチカン宮殿内のシスティナ礼拝堂の天井に「天地創造」に始まる旧約聖書の世界を、正面祭壇には壁画「最後の審判」を描いた。ミケランジェロの描く世界はとにかく壮大だ。そして、少し遅れて登場したラファエロは、ルネサンス様式絵画の完成者だよ。26歳の若さでヴァチカン宮殿「署名の間」に描いた「アテネの学堂」は、古代ギリシア文化のオールスターが登場する圧巻の構図だ！　ちなみに、プラトンはダ＝ヴィンチ、ヘラクレイトスはミケランジェロがモデルといわれているよ。ほかにも聖母マリアとイエスを描いた聖母子画を多数残しているね。"
      ],
