      "title": "スペインのアメリカ大陸進出は、コロンブスの「発見？」からだ！",
      "body": [
        "1492年、グラナダが陥落してレコンキスタが完成した年に、コロンブスはサンタ＝マリア号ほか3隻でパロス港を出港すると、69日の航海の末にカリブ海のバハマ諸島の島（サンサルバドル島と命名された）に到達したよ。さらに、ジパングと勘違いしたハイチ島をエスパニョーラ島（“スペイン”のことだね）と名づけた。ただ、その後4度の航海をおこなったにもかかわらず、コロンブスは「インディアス（アジア）に到達した！」と信じて疑わなかったから、先住民は“インディオ”（北米では英語読みで“インディアン”）、近辺の島々は“西インド諸島”と呼ばれるようになった。ホント、勘違いってコワイね。",
        "「コロンブスがインディアスに到達した！」というニュースが広がると、イギリス王ヘンリ7世もジェノヴァの探検家カボットに北西航路の探検を命じ、2度の航海で北米沿岸に到達した。フランスもカルティエの探検でカナダに到達したよ。これがのちのイギリスやフランスが北米の領有を主張する根拠になるよ。"
      ],
