      "id": "c07-l22-p03-009",
      "title": "「この大陸はアジアではない！」。そして、世界周航も実現",
      "body": [
        "また、コロンブスのインディアス到達以後、ポルトガルとスペインの船団が盛んにアメリカ大陸に進出して対立が激しくなったことから、教皇アレクサンデル6世は植民地分界線【教皇子午線】を設定し、ヴェルデ岬の西方約550kmの子午線から西側をスペイン領、東をポルトガル領と定めた。ところが「スペインに有利じゃないか」とポルトガルが抗議したから、境界を西方に移動させるトルデシリャス条約が結ばれて、スペインとポルトガルが勝手に世界を分割した。だから、インドに行く途中で遭難したポルトガル人のカブラルがブラジルに漂着すると、トルデシリャス条約のラインよりも東だからポルトガルが領有を宣言したよ。"
      ],
