      "id": "c07-l22-p03-010",
      "title": "「この大陸はアジアではない！」。そして、世界周航も実現",
      "body": [
        "その後、多くの探検家が大西洋の向こう側を探検した。ただ、どうも東回りで訪れた「アジア」の情報と合わないところも多い！　そして、アメリゴ＝ヴェスプッチによる4回のブラジル探検で、コロンブスが「発見」した土地は「アジア」ではなくヨーロッパ人にとって未知の「新大陸」であることが確認された。こうして「新大陸」は彼の名前にちなんで“アメリカ”と名づけられた。初めてこの名前を使ったのは、ドイツの地理学者ヴァルトゼーミュラーだね。そうなると、アジアの東側に大きな海がある以上、アメリカ大陸の西側にも大きな海があるはず！　1513年、スペインのバルボアが初めてパナマ地峡を横断し、大陸の向こう側に大きな海が広がっているのを確認した。彼が「南の海」と命名したのが太平洋だよ。"
      ],
