      "id": "c07-l22-p04-002",
      "title": "商業革命——ヨーロッパの国際商業の中心が大西洋沿岸へ",
      "body": [
        "しかし、ヨーロッパ諸国がアジアやアメリカ大陸に進出したことで、「大洋（ocean）」を結びつける新しい交易ネットワークが形成されて、「世界の一体化」が始まった。大西洋を南下して喜望峰経由でインド洋に進出するインド航路が開拓され、さらにアメリカ大陸への進出で大西洋にも新しいネットワークが生まれた。ヨーロッパ人たちは、アジア・アフリカ・アメリカ大陸に直接行って取引するようになり、ヨーロッパ人の交易は世界規模に拡大した。貿易を拡大したのは、大西洋沿岸のポルトガル・スペイン、のちにオランダ・イギリス・フランスなどだから、貿易の中心は地中海から大西洋沿岸に移り、リスボン（ポルトガル）、ネーデルラントのアントウェルペン【アントワープ】（スペイン領ネーデルラント）、のちにアムステルダム（オランダ）など、大西洋沿岸の都市がヨーロッパ国際商業の中心として繁栄した。一方で、地中海貿易（東方貿易）やバルト海貿易の地位が低下して、イタリア諸都市や、ハンザ同盟を形成していた北ドイツ都市の繁栄は失われていった。こうした一連の変化が「商業革命」だよ。",
        "貿易の拡大で、取引する商品も香辛料、絹、陶磁器、さらにアメリカで生産された銀や砂糖など、種類も多様化して取引量も増えた。特に、アメリカ大陸での銀や砂糖の生産では、西アフリカから運ばれた黒人奴隷が労働力として使われたから、この後、大西洋における奴隷貿易は急激に拡大することになるよ。"
      ],
