      "id": "c07-l23-p01-001",
      "title": "宗教改革前夜のドイツ。教会に搾取される「ローマの乳牛」だ！",
      "body": [
        "まず、ルターが登場する前のドイツの状況について話そう！",
        "（ドイツ）では、大諸侯の勢力が強くて政治的な統合が進まず、皇帝権が弱かった。",
        "中世の叙任権闘争のところで話したけど（第12回を確認してね！　P.207〜209）、皇帝と教皇の力関係は、結局「皇帝と諸侯どっちが強いか？」で決まるから、諸侯が強いドイツは、教会にとって「勝手に搾取しても、皇帝に文句言われない国」なんだ。当時、教皇に搾取されるドイツを「ローマの牡牛」と呼んでいたよ。「牛乳を搾り取るように、日々搾取できる」ってことだ。"
      ],
