      "id": "c07-l23-p01-004",
      "title": "ルターが「95か条の論題」で贖宥状販売を批判！",
      "body": [
        "ところが、これが思いもよらない反響を招いた。ルターの「95か条」は、ラテン語からドイツ語に翻訳されると活字で印刷（活版印刷）され、ドイツ全体に広がっていった。そりゃ、ドイツのなかにだって「贖宥状はウサンクサイ……」と思っている人もいるし、教会のなかにだって「俗物教皇レオ10世は、金儲けに熱中してる」と内心は疑問を持っている聖職者だっている。こうした教皇庁の搾取や腐敗に反発した人びとが支持したことで、気づけばルターは有名人になっていたんだよ。",
        "最初は「あの田舎学者め」程度に思っていた教皇レオ10世も、黙って見ているわけにもいかず、神学者ヨハン＝エックとルターの討論をセッティングした。このライプツィヒ討論で、ルターは「聖書に書いてあることのみ正しい！」という聖書主義の立場をとったんだけど、誘導尋問に引っ掛かり、「あなたの主張はフスの説と同じではないか！」と言われて、それを認めたんだよ。つまり、ルターは“異端”ということになっちゃった。"
      ],
