      "title": "さまざまな敵が皇帝カール5世を悩ませた！",
      "body": [
        "ここで、カール5世（スペイン王カルロス1世）時代の状況を確認しよう。スペイン王国を成立させたカトリック両王（イサベル女王とフェルナンド5世）に男児がおらず、ハプスブルク家に嫁いだ娘ファナも発狂した。結果、両王の孫にあたるファナの長男カルロスが、半ばクーデタでスペイン王に即位、スペイン王カルロス1世になった（スペイン＝ハプスブルク家）。そして、カルロスの祖父で神聖ローマ皇帝のマクシミリアン1世が亡くなると、皇帝選挙では対立候補のフランス王フランソワ1世をおさえて、神聖ローマ皇帝カール5世となったんだ。"
      ],
