      "title": "さまざまな敵が皇帝カール5世を悩ませた！",
      "body": [
        "こうしてスペイン王と神聖ローマ皇帝を兼任したカール5世の帝国は、一躍ヨーロッパの最強国になった。すでにスペインはアメリカ大陸への進出を拡大し、カルロス1世時代には、コルテスがアステカ王国を、ピサロがインカ帝国をそれぞれ征服、マゼランの世界周航を援助してフィリピンにも到達していた。さらにポトシ銀山などの中南米の鉱山から大量の銀を手に入れていた。こうした勢力を背景にして、カール5世はローマ帝国以来の「キリスト教普遍帝国」を再興しようとしたんだ。ただ、彼の帝国にはさまざまな敵がいた。まずカール5世にもっとも脅威を与えたのはオスマン帝国のスレイマン1世だよ。スレイマン1世は1526年にはモハーチの戦いでハンガリーを破ると、北上してウィーンを包囲した（第1次ウィーン包囲）。さらに、地中海でもスペインと衝突！　プレヴェザの海戦でスペイン・ヴェネツィア・教皇の連合艦隊を破ったよね。そして、つねにスペインと神聖ローマに挟まれてムカついたフランス王フランソワ1世はスレイマン1世と同盟して、カール5世に対抗したんだ。当時、フランスとハプスブルク家はイタリア戦争の真っ最中！　フランソワ1世には宗教なんて関係なかったんだね。こうした国際的な対立に加えて、神聖ローマ帝国内ではルター派諸侯が反抗したんだよ。"
      ],
