      "id": "c07-l23-p01-011",
      "title": "ルター派諸侯と皇帝の対立は、内戦にまで発展！",
      "body": [
        "ルター派の再禁止に危機感を持ったルター派諸侯たちはシュマルカルデン同盟を結成し、皇帝とカトリック派（皇帝派）諸侯に政治・軍事的に対抗することにした。オスマン帝国とフランスが同盟を結んだこともあって、カール5世はこの動きになかなか手が打てなかったんだ。ただ、フランスとの和約が成立して国際関係が落ち着き、またルターが亡くなったこともあって、カール5世はルター派諸侯への攻撃に踏み切った。1546年、ルター派がトリエント公会議への参加を拒否したことをきっかけにシュマルカルデン戦争が勃発した。このとき、カール5世は同盟軍を破ったんだけど、その後も内紛が続き、カール5世はすっかり政治にも人生にも疲れ果てて、もはや気力が尽き果てた。"
      ],
