      "id": "c07-l23-p01-012",
      "title": "ルター派諸侯と皇帝の対立は、内戦にまで発展！",
      "body": [
        "こうして、帝国内のカトリック（旧教）派と新教派は和解に向かい、1555年アウクスブルクの宗教和議が結ばれた。まず、諸侯に信仰の選択権を与え、各領邦の宗派はそれぞれ諸侯たちがカトリック、ルター派から選択することになった。ただ、個人の信仰の自由はなかったから、このあと、宗教対立は「諸侯 vs. 住民」ということになるね。さらに、カルヴァン派は除外されたよ。ちなみに、都市には「責任を持って宗派を選べる支配者がいない」という理由で、新旧両宗教の併存を認めたんだ。",
        "こののち、ルター派の領邦では各諸侯が宗教を監督する領邦教会制が確立した。神聖ローマ帝国内は宗教的にバラバラとなり、これが政治的な分裂を促すことになったんだ。また、ルター派はおもに北ドイツを中心に広がり、そこからデンマーク、ノルウェー・スウェーデンなどの北欧諸国にも拡大していったよ。"
      ],
