      "title": "ジュネーヴの改革運動にカルヴァンが招かれた！",
      "body": [
        "そうなると、もう一つ疑問が出てくる。カトリックでは「お金は蓄財を招くもの」と考えていて、お金がたまるほど地獄に近づく。だから、金融業なんかは絶対に救われない職業だよね。ただ、カルヴァンのいう「マジメに働いて、マジメに生活して、ぜいたく禁止！」をやると、お金が貯まっちゃうよね。そこでカルヴァン派は「自分の天職にマジメに励んだ結果の“利益”は、神の意思」として、結果的に営利・蓄財を認めたんだ。これって、商人や職人などの市民階級にとっては、自分たちの経済活動が宗教的に認められたことになる。だからカルヴァン派は新興市民階級に拡大して、のちの資本主義発展に貢献する思想になるよ。この関係を理論化した社会学者が、20世紀初頭に登場するマックス＝ヴェーバー（著書『プロテスタンティズムの倫理と資本主義の精神』）だよ。"
      ],
      "plainBody": [
        "そうなると、もう一つ疑問が出てくる。カトリックでは「お金は蓄財を招くもの」と考えていて、お金がたまるほど地獄に近づく。だから、金融業なんかは絶対に救われない職業だよね。ただ、カルヴァンのいう「マジメに働いて、マジメに生活して、ぜいたく禁止！」をやると、お金が貯まっちゃうよね。そこでカルヴァン派は「自分の天職にマジメに励んだ結果の“利益”は、神の意思」として、結果的に営利・蓄財を認めたんだ。これって、商人や職人などの市民階級にとっては、自分たちの経済活動が宗教的に認められたことになる。だからカルヴァン派は新興市民階級に拡大して、のちの資本主義発展に貢献する思想になるよ。この関係を理論化した社会学者が、20世紀初頭に登場するマックス＝ヴェーバー（著書『プロテスタンティズムの倫理と資本主義の精神』）だよ。"
      ],
