      "id": "c07-l23-p03-001",
      "title": "国王ヘンリ8世の離婚問題から、イギリス国教会成立！",
      "body": [
        "バラ戦争を経てテューダー朝が成立したイギリスでは、ヘンリ7世が国内の貴族勢力を抑え、王権を強化した。とはいっても、それはしょせん国内での話だよ。当時のイギリスは、ヨーロッパの二大国であるスペインとフランスに挟まれた弱小国。ヘンリ7世はスペインと同盟してなんとか生き残りを図ろうと、息子のアーサーとスペイン王女カサリンを結婚させた。ただ、アーサーが急死しちゃったから、未亡人となったカサリンと次男のヘンリ（のちのヘンリ8世）を結婚させて、教皇にもなんとか特別の許可をもらったんだ（兄の嫁と結婚するのは、教会法では近親相姦になるんだよね……）。"
      ],
      "plainBody": [
        "バラ戦争を経てテューダー朝が成立したイギリスでは、ヘンリ7世が国内の貴族勢力を抑え、王権を強化した。とはいっても、それはしょせん国内での話だよ。当時のイギリスは、ヨーロッパの二大国であるスペインとフランスに挟まれた弱小国。ヘンリ7世はスペインと同盟してなんとか生き残りを図ろうと、息子のアーサーとスペイン王女カサリンを結婚させた。ただ、アーサーが急死しちゃったから、未亡人となったカサリンと次男のヘンリ（のちのヘンリ8世）を結婚させて、教皇にもなんとか特別の許可をもらったんだ（兄の嫁と結婚するのは、教会法では近親相姦になるんだよね……）。"
      ],
