      "id": "c07-l23-p03-005",
      "title": "イギリスの宗教的混乱。“血のメアリ”がカトリックを復活！",
      "body": [
        "では次の時代に進もう。ヘンリ8世の死後、まだ幼かったエドワード6世が即位すると教義の改革も進んだよ。だって、ヘンリ8世は「離婚したい！」ってだけで国教会をつくったから、中身はカトリックとほとんど変わらない。そこで、教義をカルヴァン派に近づける一般祈祷書を制定した。ただ、儀式の面はカトリックからあまり変わらず、組織もカトリックの司教制に近い主教（監督）制がとられたんだ。",
        "その後、病弱だったエドワード6世が亡くなるとメアリ1世が即位した。メアリはヘンリ8世とカサリンの娘でイギリス初の女王だよ。彼女は、お母さんを捨てて不幸のどん底に落とした父親への恨みがかなり深かったから、周囲の反対を押し切ってスペイン国王フェリペ2世と結婚すると、イギリスにカトリックを復活し、プロテスタントを次々と処刑したから“血のメアリ（Bloody Mary）”と呼ばれた。ただ、この結婚はイギリスにとっては大失敗だ。スペインの戦争に巻き込まれたイギリスはフランスと戦争になり、大陸の最後の領土カレーを失ったんだよ。"
      ],
