      "id": "c07-l24-p01-004",
      "title": "イタリア戦争は、ハプスブルク家とヴァロワ家の壮絶な覇権争い！（続き）",
      "body": [
        "ハプスブルク家のスペイン王カルロス1世が、フランス王フランソワ1世を皇帝選挙で破って、カール5世として神聖ローマ皇帝に即位すると、三大国のうち二つを支配するハプスブルク家が一気に優勢になる！　こうしてイタリア戦争は、フランスのヴァロワ家とハプスブルク家によるヨーロッパの覇権争いになった😨。",
        "このあとは、皇帝や教皇の権威も何も関係なくなるよ。皇帝が強くなりすぎるのを恐れた教皇がフランスと組むと、カール5世はローマを攻撃した（ローマ劫掠）。すると、カール5世の国（スペインと神聖ローマ）に挟み撃ちされてるフランスは、ドイツのルター派諸侯と組み、さらにオスマン帝国のスレイマン1世とも同盟してカール5世に圧力をかけた。対するカール5世は、フランスの宿敵だったイギリスのヘンリ8世と組んだ！　ていうか、神聖ローマ皇帝までもが国教会のイギリスと組むなんて、宗教も宗派もあったもんじゃない😨。各国は、自分の国の勢力を拡大することしか考えていなかったんだよ。ただ、カール5世は国内のルター派諸侯との対立にも悩まされて政治がイヤになり、ついに息子のフェリペ2世にスペインとネーデルラントを、弟のフェルディナント1世にオーストリア・ベーメンと皇帝位をそれぞれ分けてしまった。そして、スペイン王となったフェリペ2世がフランスを破って優位に立つと、長い戦争に疲れ果てたスペインとフランスは、1559年にカトー＝カンブレジ条約を結んでイタリア戦争を終わらせた。結果、フランスはイタリアの支配権を放棄し、スペインはミラノ・ナポリ・シチリア・サルデーニャなどを獲得したよ。"
      ],
