      "title": "香辛料貿易、中国貿易、日本貿易……アジア貿易を固めたオランダ！",
      "body": [
        "オランダは東シナ海交易にも進出したよ。海禁政策をとる中国本土には直接進出できなかったけど、日本に進出して平戸に商館を置き、さらに台湾を占領してゼーランディア城を建設すると、日本と中国を結ぶ中継貿易を始めたんだ。当時の日本国内では銀や銅がたくさん採れたから、日本銀・日本銅と中国産生糸を交換すればむちゃくちゃ儲かったからね😄。特に、日本が鎖国を始めるとヨーロッパ諸国でオランダだけが貿易を許されたから、長崎の出島で貿易を続けたよ。出島に行ったことある？　あんなに狭いところにおしこまれたのにオランダが怒らなかったのは、「日本の銀や銅を独占できるなら、儲かるから問題なし😄」って思ったからだ。日本の鎖国は、世界史の目線だと「オランダが日本貿易を独占した」ってことだよ。江戸幕府にとっても、「和蘭風説書」は海外を知る重要な情報源だったんだ。ただ、17世紀後半には鄭成功に台湾を奪われてしまう。しかも、17世紀末になるとイギリスとオランダが競争しすぎたためにヨーロッパで香辛料の価格が暴落😨。もはや香辛料は珍しくなかったからね。香辛料貿易で儲からなくなったオランダは、アジア域内貿易（アジアのなかでの中継貿易）にシフトしていくんだ。"
      ],
