      "title": "ステュアート朝が成立すると、国王と議会の対立が始まる！",
      "body": [
        "エリザベス1世が未婚のまま亡くなってテューダー朝が断絶すると、スコットランド国王ジェームズ6世が迎えられ、イギリス（イングランド）王<span class=\"source-bold\">ジェームズ1世</span>として即位し、<span class=\"source-bold\">ステュアート朝</span>が成立した（スコットランドとの同君連合）。ただ、いきなり新国王に、エリザベス1世と同じバランス感覚を求めるのはムリだよ。ジェームズ1世は「国教会体制を強化する」と言ってピューリタンを弾圧したうえに、<span class=\"source-bold\">王権神授説</span>を振りかざして議会を軽視し、イギリスの政治で一番大事だった国王と議会のバランスを無視したんだよ。しかも17世紀初めのイギリスは、スペインがアントウェルペンを攻略して市場が閉鎖されて以来、毛織物の輸出が激減してめちゃくちゃ景気が悪く、しかも冬になるとテムズ川が凍っちゃうくらい寒くて、まさに「<span class=\"source-bold\">17世紀の危機</span>」だった。でも、国王は何の対策もせずに一部の特権商人を保護して、財政難を理由に新しい税や特権の拡大などの<span class=\"source-bold\">重商主義</span>政策を強化したから、議会との対立はますます深まった。「もうやってられない」と思ったピューリタンのなかには、オランダに亡命する人も現れた。そこから、さらに北米へと移住した人が<span class=\"source-bold\">ピルグリム＝ファーザーズ</span>だ。"
      ],
      "plainBody": [
        "エリザベス1世が未婚のまま亡くなってテューダー朝が断絶すると、スコットランド国王ジェームズ6世が迎えられ、イギリス（イングランド）王ジェームズ1世として即位し、ステュアート朝が成立した（スコットランドとの同君連合）。ただ、いきなり新国王に、エリザベス1世と同じバランス感覚を求めるのはムリだよ。ジェームズ1世は「国教会体制を強化する」と言ってピューリタンを弾圧したうえに、王権神授説を振りかざして議会を軽視し、イギリスの政治で一番大事だった国王と議会のバランスを無視したんだよ。しかも17世紀初めのイギリスは、スペインがアントウェルペンを攻略して市場が閉鎖されて以来、毛織物の輸出が激減してめちゃくちゃ景気が悪く、しかも冬になるとテムズ川が凍っちゃうくらい寒くて、まさに「17世紀の危機」だった。でも、国王は何の対策もせずに一部の特権商人を保護して、財政難を理由に新しい税や特権の拡大などの重商主義政策を強化したから、議会との対立はますます深まった。「もうやってられない」と思ったピューリタンのなかには、オランダに亡命する人も現れた。そこから、さらに北米へと移住した人がピルグリム＝ファーザーズだ。"
      ],
