      "id": "c07-l25-p01-003",
      "title": "チャールズ1世が専制を強めると、ついにピューリタン革命が勃発！",
      "body": [
        "ジェームズ1世のあと、息子の<span class=\"source-bold\">チャールズ1世</span>が国王に即位したんだけど、彼もまた王権神授説を信奉して、議会の同意なしに臨時の税をかけるなど、専制政治を強めた。これには議会も黙っていられなくなり、1628年、<span class=\"source-bold\">権利の請願</span>を国王に提出して、議会の同意のない課税、不当逮捕・投獄、軍法裁判の濫用などを禁止するように訴えた。これは、<span class=\"source-bold\">大憲章（マグナ＝カルタ）</span>などで認められていた歴史的な権利を再確認するものだ。ところが国王は「生意気な」と逆ギレして議会を解散し、11年間にわたって議会を開かなかった。以後、ますます国教会との関係を重視して反対派やピューリタンの弾圧を強めたから、国王と国民の対立は決定的になった。そしてこの時期に、国王に反対するジェントリにピューリタンが広がっていったんだ。"
      ],
