      "id": "c07-l25-p01-004",
      "title": "チャールズ1世が専制を強めると、ついにピューリタン革命が勃発！",
      "body": [
        "革命の発端は、同君連合だったスコットランドから起きたよ！　チャールズ1世が長老主義（カルヴァン派）をとるスコットランド国教会を、国王を首長とするイギリス国教会と同じ主教制に変えようとしたら（イギリス国教会の強制）、<span class=\"source-bold\">スコットランドで反乱</span>が起こった。「鎮圧に軍事費がかかるな……」と思ったチャールズ1世は、イギリス（イングランド）に課税しようと、のちに<span class=\"source-bold\">短期議会</span>と呼ばれる議会を招集した。しかし、11年間ぶりに開かれた議会では「今さら何を言うのですか」と激しい反発が起こったので、アタマにきた国王はわずか3週間で議会を解散しちゃったんだよ。",
        "しかし、スコットランドの反乱をおさえられなかった国王は、賠償金を支払うことになった。仕方なく、再びイギリス（イングランド）で議会を開くことになったわけだけど、議会にしてみれば「陛下、いい加減にしてください」って感じだよ。のちに<span class=\"source-bold\">長期議会</span>と呼ばれるこの議会では、国王に反対する議会派が中心になって国王への「<span class=\"source-bold\">大抗議文</span>」を提出したから、チャールズ1世は議会を武力で弾圧することを決意し、ロンドンを離れて戦闘準備に入った。対する議会派も民兵を集めて対抗したから、ついにイギリスでは内戦が始まったんだ（<span class=\"source-bold\">ピューリタン革命の勃発</span>）。"
      ],
      "plainBody": [
        "革命の発端は、同君連合だったスコットランドから起きたよ！　チャールズ1世が長老主義（カルヴァン派）をとるスコットランド国教会を、国王を首長とするイギリス国教会と同じ主教制に変えようとしたら（イギリス国教会の強制）、スコットランドで反乱が起こった。「鎮圧に軍事費がかかるな……」と思ったチャールズ1世は、イギリス（イングランド）に課税しようと、のちに短期議会と呼ばれる議会を招集した。しかし、11年間ぶりに開かれた議会では「今さら何を言うのですか」と激しい反発が起こったので、アタマにきた国王はわずか3週間で議会を解散しちゃったんだよ。",
        "しかし、スコットランドの反乱をおさえられなかった国王は、賠償金を支払うことになった。仕方なく、再びイギリス（イングランド）で議会を開くことになったわけだけど、議会にしてみれば「陛下、いい加減にしてください」って感じだよ。のちに長期議会と呼ばれるこの議会では、国王に反対する議会派が中心になって国王への「大抗議文」を提出したから、チャールズ1世は議会を武力で弾圧することを決意し、ロンドンを離れて戦闘準備に入った。対する議会派も民兵を集めて対抗したから、ついにイギリスでは内戦が始まったんだ（ピューリタン革命の勃発）。"
      ],
