      "title": "ピューリタン革命は、対立関係をしっかりおさえよう！",
      "body": [
        "独立派のクロムウェルは「もっとまじめな、規律正しい軍隊をつくらなきゃいけない」と考え、ヨーマンを中心に<span class=\"source-bold\">鉄騎隊</span>をつくった。鉄騎隊っていうのは、鉄製の武器でガチガチに固めたってわけじゃなくて、まじめなピューリタンだけを集めてつくった「<span class=\"source-bold\">鉄の信仰と鉄の規律</span>」を持つ軍隊で、彼らが活躍した<span class=\"source-bold\">マーストン＝ムーアの戦い</span>で王党派を破った。しかも略奪をしなかったから、民衆は「みんな鉄騎隊ならいいのに……」と言い始めたんだ。これを見た議会派の指導者たちは「こうなったら、議会軍をすべて鉄騎隊みたいにしよう！」と、クロムウェルを中心に「<span class=\"source-bold\">ニューモデル軍</span>」を編成、国王と妥協しようとする長老派の軍司令官を追放して、素人集団だった議会軍を近代的な軍隊に変えた。そして1645年、<span class=\"source-bold\">ネーズビーの戦い</span>で議会軍が決定的な勝利を収めたんだ。国王チャールズ1世はスコットランドに逃亡したんだけど、身柄を議会派に引き渡された。"
      ],
      "plainBody": [
        "独立派のクロムウェルは「もっとまじめな、規律正しい軍隊をつくらなきゃいけない」と考え、ヨーマンを中心に鉄騎隊をつくった。鉄騎隊っていうのは、鉄製の武器でガチガチに固めたってわけじゃなくて、まじめなピューリタンだけを集めてつくった「鉄の信仰と鉄の規律」を持つ軍隊で、彼らが活躍したマーストン＝ムーアの戦いで王党派を破った。しかも略奪をしなかったから、民衆は「みんな鉄騎隊ならいいのに……」と言い始めたんだ。これを見た議会派の指導者たちは「こうなったら、議会軍をすべて鉄騎隊みたいにしよう！」と、クロムウェルを中心に「ニューモデル軍」を編成、国王と妥協しようとする長老派の軍司令官を追放して、素人集団だった議会軍を近代的な軍隊に変えた。そして1645年、ネーズビーの戦いで議会軍が決定的な勝利を収めたんだ。国王チャールズ1世はスコットランドに逃亡したんだけど、身柄を議会派に引き渡された。"
      ],
