      "id": "c07-l25-p02-006",
      "title": "ウィリアム3世のもとで、英仏植民地抗争が始まった！",
      "body": [
        "ウィリアム3世が亡くなったあと、メアリの妹の<span class=\"source-bold\">アン女王</span>が即位した（オランダとの同君連合は解消）。とはいっても、名誉革命以降、政治的な決定は議会が中心だからね。アン女王の時代には、<span class=\"source-bold\">スコットランドが併合</span>されて、<span class=\"source-bold\">グレートブリテン王国（大ブリテン王国）</span>ができたよ。これは同君連合だったけど、これでスコットランド議会が廃止になって、スコットランドにもイギリス議会の議席が割り振られた。それから、この時代にはスペイン継承戦争とアン女王戦争もあるんだけど、植民地抗争は第27回でまとめて話そう！　ただ、アン女王は後継者となる子どもを幼くして次々となくし、しかも晩年はブランデーの飲みすぎで自分で歩けないほどの肥満になった。アン女王の棺桶は正方形だったらしいよ。"
      ],
