      "id": "c07-l25-p04-008",
      "title": "「自然国境説」による侵略戦争が、さらにフランスの財政を圧迫！",
      "body": [
        "その後も、ルイ14世は領土拡大への野望を捨てず、ライン左岸への進出を狙って<span class=\"source-bold\">ファルツ継承戦争［アウクスブルク同盟戦争］</span>を起こしたんだけど、今度はハプスブルク家（スペインと神聖ローマ皇帝）がスウェーデン・イギリス・オランダと<span class=\"source-bold\">アウクスブルク同盟</span>を結んで対抗し、しかも名誉革命でオランダと同君連合になったイギリスが、北米の植民地に攻め込んできた（<span class=\"source-bold\">ウィリアム王戦争</span>）。ここから、イギリスとフランスはナポレオン戦争までずっと戦争することになるよ（<span class=\"source-bold\">第2次英仏百年戦争［英仏植民地戦争］</span>）。"
      ],
      "plainBody": [
        "その後も、ルイ14世は領土拡大への野望を捨てず、ライン左岸への進出を狙ってファルツ継承戦争［アウクスブルク同盟戦争］を起こしたんだけど、今度はハプスブルク家（スペインと神聖ローマ皇帝）がスウェーデン・イギリス・オランダとアウクスブルク同盟を結んで対抗し、しかも名誉革命でオランダと同君連合になったイギリスが、北米の植民地に攻め込んできた（ウィリアム王戦争）。ここから、イギリスとフランスはナポレオン戦争までずっと戦争することになるよ（第2次英仏百年戦争［英仏植民地戦争］）。"
      ],
