      "id": "c07-l26-p01-007",
      "title": "多国間の国際条約、ウェストファリア条約が結ばれた！",
      "body": [
        "国際問題では、おもに領土問題が決められたよ。フランスは<span class=\"source-bold\">アルザス地方</span>に加えロレーヌ地方の一部（ヴェルダン・メス・トゥール）を獲得して、部分的とはいえライン川まで進出した。スウェーデンは<span class=\"source-bold\">西ポンメルン</span>など（北ドイツ沿岸やエルベ川の河口付近）を獲得してバルト海地域で勢力を拡大した。さらに、フランスとスウェーデンは、神聖ローマ帝国議会の議席を得て、ドイツの政治に口出しできるようになった。あっ！　帝国議会というのは「神聖ローマ帝国内に領土を持つ領邦君主が参加する議会」だから、フランスとスウェーデンが獲得した領土と帝国議会の議席がセットね。そのほか、プロイセンは<span class=\"source-bold\">東ポンメルン</span>を獲得して北ドイツで勢力を拡大し、事実上独立していた<span class=\"source-bold\">オランダとスイス</span>が、正式に独立を認められたよ。"
      ],
