      "id": "c07-l26-p01-008",
      "title": "三十年戦争のあと、ヨーロッパはどうなったんだろう？",
      "body": [
        "次は、二つに分けて三十年戦争の歴史的意義を考えてみよう！　まずは国際問題からね。ウェストファリア条約は、優勢なまま終戦に持ち込んだフランスの「ハプスブルク家を抑えたい！」って意向が強く反映され、ハプスブルク家に対して<span class=\"source-bold\">フランス（ブルボン家）が優位</span>となり、大陸ヨーロッパでのフランスの覇権がほぼ確立された。北欧ではスウェーデンが覇権を確立し、これによりハンザ同盟は事実上終焉を迎えたんだ。もっとも、ハンザ同盟の衰退はスウェーデンの問題よりも、オランダやイギリスの重商主義政策や、ドイツの諸邦（諸侯）が強くなってハンザ同盟の都市に支配を伸ばしたことの影響が大きいよ。そして、三十年戦争によってヨーロッパでは<span class=\"source-bold\">主権国家体制</span>が確立したといわれる。これは、最後の普遍国家だった神聖ローマ帝国がほぼ完全な主権を持つ領邦国家に分裂して国境が定まったこと、史上初の国際会議を開いて秩序を回復し、勢力均衡体制をつくったことが要因だ。そして、この戦争の惨禍を見た<span class=\"source-bold\">グロティウス</span>が『<span class=\"source-bold\">戦争と平和の法</span>』のなかで「国家間にもルールがあるべきだ」と主張して<span class=\"source-bold\">国際法</span>を提唱し、実際にウェストファリア条約という多国間の国際条約が成立して、近代国際法の出発点になったんだよ。"
      ],
      "plainBody": [
        "次は、二つに分けて三十年戦争の歴史的意義を考えてみよう！　まずは国際問題からね。ウェストファリア条約は、優勢なまま終戦に持ち込んだフランスの「ハプスブルク家を抑えたい！」って意向が強く反映され、ハプスブルク家に対してフランス（ブルボン家）が優位となり、大陸ヨーロッパでのフランスの覇権がほぼ確立された。北欧ではスウェーデンが覇権を確立し、これによりハンザ同盟は事実上終焉を迎えたんだ。もっとも、ハンザ同盟の衰退はスウェーデンの問題よりも、オランダやイギリスの重商主義政策や、ドイツの諸邦（諸侯）が強くなってハンザ同盟の都市に支配を伸ばしたことの影響が大きいよ。そして、三十年戦争によってヨーロッパでは主権国家体制が確立したといわれる。これは、最後の普遍国家だった神聖ローマ帝国がほぼ完全な主権を持つ領邦国家に分裂して国境が定まったこと、史上初の国際会議を開いて秩序を回復し、勢力均衡体制をつくったことが要因だ。そして、この戦争の惨禍を見たグロティウスが『戦争と平和の法』のなかで「国家間にもルールがあるべきだ」と主張して国際法を提唱し、実際にウェストファリア条約という多国間の国際条約が成立して、近代国際法の出発点になったんだよ。"
      ],
