        "じゃあ、啓蒙専制君主ってなんだろう？　これね、「絶対王政をやる言い訳」って考えたほうがわかりやすいよ。すでにイギリスでは革命が終わり、フランスでは啓蒙思想が拡大してるから、今さら王権神授説はムリ。だから啓蒙思想（特に社会契約説）を利用して、「遅れている国を近代化するために国王が権力を握っている」という理論をつくり、君主主導の“上からの近代化”で富国強兵を進めた。これが啓蒙専制君主だ。さらに古い体制を倒すというタテマエで貴族を抑え込み、王権を強めるという意味もあった。どっちにしても言い訳だな……。"
