        "そこでピョートル1世は、西欧の進んだ技術を取り入れるため、大使節団を送り、自分もお忍びで同行することにした。オランダでは自らハンマーを握って造船所で働いて「モスクワの王様は船大工だよ」と噂されたり、イギリス海軍の演習を見て「すばらしい」と大興奮!!　このときにロシアに連れて帰った技術者たちが、ロシアの西欧化を支えることになるよ。"
