      "id": "c07-l26-p04-006",
      "title": "西欧化を進めたピョートル1世が、ロシアの絶対主義を確立！",
      "body": [
        "そして帰国後、ピョートル1世はロシアの政治・社会を徹底的に<span class=\"source-bold\">西欧化</span>しようと「<span class=\"source-bold\">上からの近代化</span>」を進めた。徴兵制に基づく常備軍を創設し、西欧技術を使って産業を育成し、その財源を確保するために税制も改革した。また官僚制の整備や教会改革なども一気に実行すると、さらに「ひげは遅れた社会の象徴だ！」と言って、ひげを伸ばした者に高い税をかけた。ピョートル1世はいろいろ極端だな。でも近代化のウラで、農民は軍役や重税を課されて、苦しい生活に追い込まれたんだよ。"
      ],
