      "id": "c07-l26-p04-011",
      "title": "クーデタで女帝エカチェリーナ2世が誕生！",
      "body": [
        "結局、改革や美術品収集のためのお金は農民から搾り取ったから、農民はコサックのところに逃げ始める。そして、南ロシアではコサック出身の<span class=\"source-bold\">プガチョフの農民反乱</span>が起きたんだ。プガチョフは「ワタシはピョートル3世である。帝位を奪い返すために戦う」と言ってコサックを集めて、農奴解放などを求めた。これに対しエカチェリーナ2世は「バカなこと言わないで。ピョートルはもう死んでるわ……」と反乱軍を容赦なく鎮圧し、プガチョフも処刑した。そして反乱ののち、エカチェリーナ2世は貴族の特権を保護して、<span class=\"source-bold\">農奴制を強化（再版農奴制）</span>するなど反動化したんだよ。ほらね、啓蒙専制君主っていうのは、しょせん絶対王政でしょ。"
      ],
