      "id": "c07-l27-p02-002",
      "title": "イギリスで最初に産業革命が始まったのはなぜだろう？",
      "body": [
        "イギリスで産業革命が始まった背景はいろいろあるけど、一つ目は工業の伝統だよ。工業の発達はまず、商人（問屋）が原料や道具を職人や農民に貸して、職人が家で作業する<span class=\"source-bold\">問屋制【問屋制家内工業／プロト工業】</span>から始まった。簡単に言うと、「材料買ってきて、家でつくって、街の問屋に売る」。ただ、原料や製品をいちいち運ぶのは大変……。「だったら、職人が工場に通えばいい！」と工場に職人や労働者を集めて分業で生産する<span class=\"source-bold\">工場制手工業【マニュファクチュア】</span>になった。要するに労働者が「通勤」するんだよ。イギリスではすでにマニュファクチュアによる毛織物工業が発展していたから、あとは工場に機械が入れば……ほら産業革命だ！"
      ],
