      "id": "c07-l27-p02-004",
      "title": "イギリスで最初に産業革命が始まったのはなぜだろう？",
      "body": [
        "ほかにも、鉄、石炭などの資源が豊富で、海外植民地からも資源や綿花などの原材料を得られたし、さらに、議会政治が確立されて政治が安定していて、ギルドの廃止や特権の廃止も進んだから、ほかの国に比べて自由な経済活動ができたことも、工業化が進んだ背景だ。そして、マックス＝ヴェーバーが指摘した、「プロテスタンティズムが勤勉な労働を奨励したこと」も、資本主義が発展する前提だね。"
      ],
