      "title": "〈パリ条約後の北米【1763】〉",
      "body": [
        "北米の<span class=\"source-bold\">イギリス領13植民地</span>は建設された経緯がバラバラだから、ザックリと分けると北部と南部で特徴が違うよ。北部は寒くて農業にはイマイチだから<span class=\"source-bold\">商工業が中心</span>で、農業も中小自作農がほとんどだよ。1620年に<span class=\"source-bold\">メイフラワー号</span>でやってきて<span class=\"source-bold\">プリマス植民地</span>を建設した<span class=\"source-bold\">ピルグリム＝ファーザーズ</span>に代表されるように、北部に移住してきた人は、本国の弾圧から自由を求めて逃げてきた場合が多く、もともと富裕人が多くて、反英的な傾向が強かった。ちなみに、「自由・平等」を誓って上陸したピルグリム＝ファーザーズを、アメリカ人は「<span class=\"source-bold\">建国の始祖</span>」として神話化しているよ。ほかに、ピューリタンが建設した<span class=\"source-bold\">マサチューセッツ植民地</span>は、中心地の<span class=\"source-bold\">ボストン</span>が独立戦争で重要な街だったし、新教徒の一派<span class=\"source-bold\">クウェーカー教徒</span>のためにつくられた<span class=\"source-bold\">ペンシルヴェニア植民地</span>の中心地<span class=\"source-bold\">フィラデルフィア</span>は、独立戦争前後にアメリカの実質的な首都だった街だよ。"
      ],
      "plainBody": [
        "北米のイギリス領13植民地は建設された経緯がバラバラだから、ザックリと分けると北部と南部で特徴が違うよ。北部は寒くて農業にはイマイチだから商工業が中心で、農業も中小自作農がほとんどだよ。1620年にメイフラワー号でやってきてプリマス植民地を建設したピルグリム＝ファーザーズに代表されるように、北部に移住してきた人は、本国の弾圧から自由を求めて逃げてきた場合が多く、もともと富裕人が多くて、反英的な傾向が強かった。ちなみに、「自由・平等」を誓って上陸したピルグリム＝ファーザーズを、アメリカ人は「建国の始祖」として神話化しているよ。ほかに、ピューリタンが建設したマサチューセッツ植民地は、中心地のボストンが独立戦争で重要な街だったし、新教徒の一派クウェーカー教徒のためにつくられたペンシルヴェニア植民地の中心地フィラデルフィアは、独立戦争前後にアメリカの実質的な首都だった街だよ。"
      ],
