        "この世論に独立へと世論を傾けたのが、（トマス＝）ペインによるパンフレット『コモン＝センス』だよ。このなかでペインは、イギリス国王ジョージ3世を「イギリス王国の賢獣」とののしって読者をあおりながら、「分離独立することが、アメリカ大陸にとって真に利益になる」として、共和政を樹立する必要性を訴えた。『コモン＝センス』は人口約230万人だったアメリカで、3カ月のうちになんと12万部も売れる大ベストセラーになったんだ。"
