      "body": [
        "こうしてイギリスが国際的に孤立して、アメリカに独立戦争の光明が見え始めた。イギリス軍は苦戦して追い込まれ、1781年ヴァージニア州の<span class=\"source-bold\">ヨークタウン</span>でアメリカ・フランス連合軍が大勝した。<span class=\"source-bold\">ヨークタウンの戦い</span>で敗れたイギリスはアメリカとの和平交渉に入ることを決め、事実上、独立戦争は終結したんだ。そして2年後の1783年、イギリスはアメリカと<span class=\"source-bold\">パリ条約</span>を結んでアメリカ合衆国の完全独立を承認し、さらにアメリカに<span class=\"source-bold\">ミシシッピ川以東のルイジアナ</span>を割譲した。これで「あわよくばルイジアナを取り返せる……」と思っていたフランスの野望は打ち砕かれた……ていうか、イギリスはフランスにルイジアナを渡したくないんだよ。そして、イギリスとフランス・スペインの<span class=\"source-bold\">ヴェルサイユ条約</span>でフランスが得たものはセネガルと西インド諸島の一部（ドミニカ）だけ。こりゃ、フランスは大損だ……。そしてスペインには<span class=\"source-bold\">フロリダ</span>とミノルカ島を割譲したんだ。"
      ],
