      "id": "c07-l28-p01-002",
      "title": "旧体制の危機。絶対王政が行き詰まり、フランスは破産寸前だ！",
      "body": [
        "ただ、18世紀には旧体制がすでにほころび始めていた。国王が中央集権を狙うと、貴族たちが「私たちの特権を奪うのか」と反発するし、一方で、経済発展で現れた新興市民（ブルジョワジー）は「国王と結びついた特権や規制を打ち破って、自由な活動をしたい」と、絶対王政を批判した。彼らが当時流行していた<span class=\"source-bold\">啓蒙思想</span>を使って王権を批判すると、カフェやさまざまなサークルを舞台に「世論」が生まれ、国王も世論を完全に無視することはできなくなった。",
        "危機の時代の国王に必要なものは、「決断力」と「リーダーシップ」なんだろうけど、国王<span class=\"source-bold\">ルイ16世</span>は全く正反対だった。いや、人としては「いい人」なんだよ。子ども好きで優しくてマジメ、頭も悪くない。ただ、優柔不断で気が弱い、人の意見に流される……。平和な時代なら、啓蒙専制君主の代表といわれたかもしれないけど……激動を乗り切るパワーはなかったんだ。"
      ],
