      "id": "c07-l28-p01-004",
      "title": "ついに全国三部会を招集。しかし、身分間の対立から国民議会が成立！",
      "body": [
        "特権身分は「新しく課税するなら、全国三部会を開いてください！」と主張し始めた。仕方なくルイ16世は<span class=\"source-bold\">全国三部会</span>の招集を決めて、再びネッケルを財務総監にしたんだけど、ネッケルには「財政再建をするには特権身分に課税するしかありませんから」と言われたんだ。この全国三部会が<span class=\"source-bold\">フランス革命</span>の引き金になるなんて、全く考えてなかっただろうね。このあと、さまざまな階層の利害が絡み合って（<span class=\"source-bold\">複合革命</span>）、思いもよらぬ展開になるからね。",
        "こうして、ルイ13世時代に停止されて以来175年ぶりに、<span class=\"source-bold\">ヴェルサイユ宮殿で全国三部会（三部会）</span>が開催された。第一身分（聖職者）と第二身分（貴族）が約300人ずつ、そしてネッケルの意見で人数が増やされた第三身分（平民）が約600人。第三身分代表のなかには“平民から選ばれた”貴族出身の<span class=\"source-bold\">ミラボー</span>や聖職者の<span class=\"source-bold\">シェイエス</span>などもいて、彼らが革命初期の指導者になるよ！　特にシェイエスが書いた『<span class=\"source-bold\">第三身分とは何か</span>』という特権身分を批判するパンフレットは、平民たちが権利に目覚めるきっかけにもなった。この時点で、全国三部会に向かう各身分は考えてることが違う。国王は貴族の免税特権を奪って王権を強化したいけど、逆に特権身分は王権を抑えて伝統的な特権を維持したい。そして第三身分は、旧体制そのものを打破したい。"
      ],
