      "id": "c07-l28-p01-006",
      "title": "ついに全国三部会を招集。しかし、身分間の対立から国民議会が成立！",
      "body": [
        "これに対し保守派の貴族たちは、国王に「平民たちの暴走です」と迫り、第三身分の会議場を閉鎖した。何も知らずにやってきた第三身分の議員たちは、議場が閉鎖されているのを見て怒った。でもあきらめない！　彼らは、宮殿内の室内テニスコートに集まり、「憲法を制定するまでは、決して国民議会を解散しない」と固く誓ったんだ。この<span class=\"source-bold\">球戯場の誓い</span>は王政への挑戦だよ。その後の国王の働きかけは手遅れで、第一身分の多くが国民議会に合流し、50人近くの第二身分もこれに続いたから、ルイ16世はこの動きを認めるしかなかった。そして議会は、<span class=\"source-bold\">憲法制定国民議会</span>と名前をかえ、フランスは立憲王政に向かって進み始めたんだ。",
        "ただね、ルイ16世の優柔不断さが、ここで問題になる……。国王自身も「改革をしないと王政は破綻する」けど、でも「王政の伝統は守らなければいけない」というジレンマで揺れているんだよ。国王は全国の軍に命令を出した。その命令とは「7月13日までに、パリとヴェルサイユに集結せよ！」だったんだ。"
      ],
