      "id": "c07-l28-p02-004",
      "title": "食糧難からパリの奥さんが立ち上がり、ヴェルサイユに殺到！",
      "body": [
        "バスティーユ襲撃後、パリではパン屋に並んでもパンが手に入らない食糧難になった。パリの奥さんたちは、「国王様になんとかしてもらおう！」「悪いのは王妃なんだよ！」と言いだした。ルイ16世の王妃はマリア＝テレジアの娘<span class=\"source-bold\">マリ＝アントワネット</span>。ドイツ人がフランスの宮廷を食い荒らしているといわれて、一番人気がなかった。そうこういってるうちに「いざヴェルサイユへ！」と約7000人の女性たちが雨のなかを歩き出した。さらにラ＝ファイエット指揮下の国民衛兵2万人も続く……。ヴェルサイユ宮殿に着いた女性たちは国民議会の議場になだれ込み、「パリにはパンがないのです」と訴え、議会は民衆の勢いを利用して<span class=\"source-bold\">封建的特権廃止</span>と<span class=\"source-bold\">人権宣言</span>を王に認めさせた。宮殿の中庭は殺気立った群衆であふれかえり、もはや王は抵抗できない。ルイ16世と、ラ＝ファイエットに導かれたマリ＝アントワネットがバルコニーに立つと、群衆は「国王陛下をパリへ」と叫んだ。この<span class=\"source-bold\">ヴェルサイユ行進</span>を機に、国王ルイ16世一家は「国王万歳！」の声とともにパリのテュイルリー宮殿に移され、続いて国民議会もパリに移動した。民衆はまだ国王を信じているから、これで騒乱は急速に収まったんだ。"
      ],
