      "id": "c07-l28-p04-005",
      "title": "ついにジロンド派を追放。恐怖政治（ジャコバン独裁）が始まった！",
      "body": [
        "議会での主導権を完全に握った<span class=\"source-bold\">山岳派【ジャコバン派】</span>は、パリの民衆、農民などの下層民を味方につける政策を次々と進めたよ。新たにつくられた<span class=\"source-bold\">1793年憲法</span>は、主権在民や<span class=\"source-bold\">男子普通選挙</span>を定めたほか、人民の生活権、労働権なども認めた世界初の民主的な憲法だったけど、革命の激化を理由にして「平和になるまで」は施行が延期された（結局施行されなかった……）。さらに、亡命した貴族の土地は市民に安く分けられ、さらに<span class=\"source-bold\">封建的特権（地代）の無償廃止</span>も宣言されたよ。これでフランスの農民はタダで土地を手に入れた。もっとも、すでに農民のほとんどが封建地代を払っていなかったし、1792年に封建地代は“条件つき（領主が証書を提出しなかった場合のみ）”で廃止されていたから、それらを正式に認めたものだ。そして、民衆の生活を苦しめているのは「パンを買い占める悪徳商人だ」として、生活必需品や食糧と賃金の上限を設定する<span class=\"source-bold\">最高価格令</span>も出した。といっても、ただでさえ足りないのに値段を下げたらあっという間に売り切れる。そうすると、見せしめにパン屋や役人が処刑されたんだよ。",
        "また、かつては王権と結びつき、ヴァンデーの反乱を反革命に利用しようとしたカトリック教会も標的になった。1793年10月にグレゴリウス暦が廃止されて<span class=\"source-bold\">革命暦【共和暦】</span>が採用されると、民衆運動と結びついた<span class=\"source-bold\">キリスト教否定運動</span>が過激になり、ジャコバン派内での過激派だった<span class=\"source-bold\">エベール</span>は理性崇拝の宗教を導入した。ていうか、理性と信仰って対極のほうなんだけど……。"
      ],
