      "title": "エスカレートする「恐怖政治」は、ついに山岳派内部にまで……",
      "body": [
        "もはや、ロベスピエールには革命の理想しか見えていなかった。自分の信念が正しいと信じて疑わなかった彼にとって、「暴政に対する自由の戦争」を妨害するすべての者は敵だった。「外国軍を倒すためには人民を結集しなければならない。だからその団結を乱す者は、すべて敵だ」とロベスピエールは考えた。こうしてジャコバン派内の分派も「革命の敵」として、恐怖政治の標的になった。民衆運動を背景に圧力をかける極左派の<span class=\"source-bold\">エベール</span>は「陰謀」の罪で処刑され、恐怖政治を批判した右派の<span class=\"source-bold\">ダントン</span>も、「汚職」の罪で処刑された。ダントンはこれまでも人びとに祖国愛を訴え続けてきて、党派の利害を超えてジロンド派と山岳派を仲介できる数少ない人物だった。要は革命派で一番の大物だから、ダントンを処刑して喜ぶのはむしろ「今は隠れている反革命派」だよ。"
      ],
