      "body": [
        "こうして、強い指導者としての期待を一身に受けたナポレオンは対外遠征に向かっていくよ。1800年の<span class=\"source-bold\">イタリア遠征（第2次）</span>では、<span class=\"source-bold\">マレンゴの戦い</span>で再びオーストリアに圧勝した。フランスの包囲どころかイギリスのほうが孤立したから、1802年、長い長い<span class=\"source-bold\">アミアンの和約</span>を結び、お互いに多くの占領地を返還し合った。これで第2回対仏大同盟は崩壊し、フランスと戦争している国が一つもなくなった。そして、フランスに10年ぶりの平和をもたらしたナポレオンは、国内の絶大な支持を背景に、国民投票で<span class=\"source-bold\">終身統領</span>になったよ。"
      ],
