        "もう一つが家族の尊重だ。「家族は尊重されなければならない」っていう条文の直後に、「妻は夫に従うこと」と書いてあるから男女不平等だ。男女平等が出てくるのは、だいたい第一次世界大戦後だよ。そして、ナポレオン自身は死ぬ直前に「余の栄誉は戦勝ではなく、この民法典である」って言ってるくらい、この法典が自慢だったんだよ。"
