      "title": "ナポレオンが連戦連勝！　いよいよ大陸制覇だ",
      "body": [
        "トラファルガーの海戦で敗れたナポレオンは、陸軍を一気にドイツ方面へと進め、1805年12月、ベーメンのアウステルリッツでオーストリア・ロシア連合軍と激突した。これが<span class=\"source-bold\">アウステルリッツの戦い【三帝会戦】</span>だ。三帝（3人の皇帝）とは、フランス皇帝ナポレオン1世、オーストリアの神聖ローマ皇帝フランツ2世、ロシア皇帝アレクサンドル1世だよ。この戦いで、陸軍では圧倒的な強さを誇るナポレオン軍は、オーストリア・ロシア連合軍に圧勝、プレスブルクの和約を結んで第3回対仏大同盟を崩壊させ、ナポレオンのイタリア支配権を認めさせた。この知らせを聞いたイギリスのピットはついに倒れてしまった。だってネルソンを失って、しかもナポレオンが圧倒的でしょ。そりゃ血管も切れる😨。「ああ、私はなんという状態で祖国を放置するのか！」との言葉を残して、失意のうちに病死したんだよ。"
      ],
      "plainBody": [
        "トラファルガーの海戦で敗れたナポレオンは、陸軍を一気にドイツ方面へと進め、1805年12月、ベーメンのアウステルリッツでオーストリア・ロシア連合軍と激突した。これがアウステルリッツの戦い【三帝会戦】だ。三帝（3人の皇帝）とは、フランス皇帝ナポレオン1世、オーストリアの神聖ローマ皇帝フランツ2世、ロシア皇帝アレクサンドル1世だよ。この戦いで、陸軍では圧倒的な強さを誇るナポレオン軍は、オーストリア・ロシア連合軍に圧勝、プレスブルクの和約を結んで第3回対仏大同盟を崩壊させ、ナポレオンのイタリア支配権を認めさせた。この知らせを聞いたイギリスのピットはついに倒れてしまった。だってネルソンを失って、しかもナポレオンが圧倒的でしょ。そりゃ血管も切れる😨。「ああ、私はなんという状態で祖国を放置するのか！」との言葉を残して、失意のうちに病死したんだよ。"
      ],
