        "ところが、その後イギリスでは議会が新しい国王を選ぶ名誉革命が起きた。これを目の当たりにしたロックは、「すばらしい！　それでOKだ。国王に権利を預けたといっても、それは“自分たちの権利を守る”ためなのだから、権利を侵害する悪い国王からは“預けた権利を返してもらえばよい！”」と、ホッブズが王権擁護に使った社会契約説を発展させて、革命を擁護する理論をつくった。これが社会契約説に基づく「人民主権」と「抵抗権【革命権】」だよ。ロックは『統治二論【市民政府二論】』で、この考え方を使って名誉革命を正当化したんだ。",
